void __stdcall DrawBackgroundHelpMenu() {
    BOOL bMiniPanelShown = ui::GetUIFlag(UI_MINIPANEL);
    if (!bMiniPanelShown) {
      ui::SetUIFlag(UI_MINIPANEL, UI_SET, 0);
      gbMiniPanel = 1;
    }

    DWORD eResMode = D2gfx::D2GFX::D2GFX_GetResolutionMode();
    if (eResMode == 2) {
      DrawBorderXpac();
      DrawSellBtn();
      DrawYellowBullet();
      DrawWhiteBulletXpac();
      DRAW_UI_HelpXpac();
      return;
    }

    DrawBorderClassic();
    DrawSellBtn();
    DrawYellowBullet();
    DrawWhiteBulletClassic();
    DRAW_UI_HelpClassic();
}

void __stdcall INPUT_HelpCloseButtonUp(D2UIMouseMsgStrc * pMsg) {
    uint16_t nMouseY;
    nMouseY = pMsg->uLParam.sMousePos.nMouseY;
    uint32_t nRelX;
    nRelX = (uint32_t)pMsg->uLParam.sMousePos.nMouseX;
    if (gpHelpCloseButton) {
      DWORD eResMode;
      eResMode = D2gfx::D2GFX::D2GFX_GetResolutionMode();
      if (eResMode == 2) {
        nRelX -= 0x2ad;
      } else {
        nRelX -= 0x20d;
      }
      if (nRelX <= 0x20 && (uint32_t)(nMouseY - 0x18) <= 0x20) {
        ui::SetUIFlag(UI_HELPSCREEN, UI_TOGGLE, 0);
        HELP_HideMiniPanel();
        goto consume_click;
      }
    }

    gpHelpCloseButton = 0;
    GAME::Game::GAMEDATA_ClearQueuedClicks();
    consume_click:
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

void __fastcall HELP_SetUIVarW(eD2UIvars eUIVar, eD2UIvarsSetType eUIVarSetType, uint32_t dwArg1) {
    DWORD dwUnused;
    ui::SetUIFlag(eUIVar, eUIVarSetType, dwUnused);
    if (!gbMiniPanel) {
      return;
    }

    ui::SetUIFlag(UI_MINIPANEL, UI_RESET, 0);
    gbMiniPanel = 0;
}

